+import React from "react";
+import { mount } from "enzyme";
+import ExternalLink from "../../../../src/components/views/elements/ExternalLink";
+
+describe("ExternalLink", () => {
+    it("opens safely in a new tab and announces that behavior", () => {
+        const wrapper = mount(
+            <ExternalLink href="https://example.org" className="custom" title="Example">Example</ExternalLink>,
+        );
+        const link = wrapper.find("a");
+
+        expect(link.prop("href")).toBe("https://example.org");
+        expect(link.prop("target")).toBe("_blank");
+        expect(link.prop("rel")).toBe("noreferrer noopener");
+        expect(link.prop("title")).toBe("Example");
+        expect(link.hasClass("mx_ExternalLink")).toBe(true);
+        expect(link.hasClass("custom")).toBe(true);
+        expect(wrapper.find(".mx_ExternalLink_icon").prop("aria-hidden")).toBe("true");
+        expect(wrapper.find(".mx_ExternalLink_newTab").text()).toContain("Opens in a new tab");
+    });
+
+    it("forwards an explicit target", () => {
+        const wrapper = mount(<ExternalLink href="/local" target="_self">Local</ExternalLink>);
+        expect(wrapper.find("a").prop("target")).toBe("_self");
+        expect(wrapper.find(".mx_ExternalLink_newTab").exists()).toBe(false);
+    });
+});
